package com.realstant.nativegame; import android.content.*; public final class SettingsStore { private final SharedPreferences p; public SettingsStore(Context c){p=c.getSharedPreferences("settings",0);} public void save(GameSettings s){p.edit().putInt("quality",s.graphics.quality.ordinal()).putInt("input",s.input.ordinal()).putInt("camera",s.camera.ordinal()).apply();} public void load(GameSettings s){s.graphics.quality=QualityLevel.values()[p.getInt("quality",2)];s.input=InputProfile.values()[p.getInt("input",0)];s.camera=CameraMode.values()[p.getInt("camera",0)];} }
